"use client";

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "radix-ui";

import { useV4PortalContainer } from "../scope";
import { Button } from "./button";

import { useOwnedEscape } from "../lib/use-owned-escape";
import { cn } from "../lib/utils";

import overlay from "./overlay.module.css";

function AlertDialog({ ...props }: React.ComponentProps<typeof AlertDialogPrimitive.Root>) {
  return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />;
}

const AlertDialogTrigger = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Trigger>
>(({ ...props }, ref) => {
  return <AlertDialogPrimitive.Trigger ref={ref} data-slot="alert-dialog-trigger" {...props} />;
});
AlertDialogTrigger.displayName = "AlertDialogTrigger";

function AlertDialogPortal({ ...props }: React.ComponentProps<typeof AlertDialogPrimitive.Portal>) {
  return (
    <AlertDialogPrimitive.Portal
      container={useV4PortalContainer()}
      data-slot="alert-dialog-portal"
      {...props}
    />
  );
}

const AlertDialogOverlay = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Overlay>
>(({ className, ...props }, ref) => {
  return (
    <AlertDialogPrimitive.Overlay
      ref={ref}
      data-slot="alert-dialog-overlay"
      className={cn("z-50", overlay.scrim, className)}
      {...props}
    />
  );
});
AlertDialogOverlay.displayName = "AlertDialogOverlay";

const AlertDialogContent = React.forwardRef<
  React.ComponentRef<typeof AlertDialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Content> & {
    size?: "default" | "sm";
  }
>(({ className, size = "default", onEscapeKeyDown, ...props }, ref) => {
  const escape = useOwnedEscape(ref, onEscapeKeyDown);
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Content
        ref={escape.ref}
        data-slot="alert-dialog-content"
        data-size={size}
        className={cn(
          "group/alert-dialog-content z-50 data-[size=default]:max-w-xs data-[size=sm]:max-w-xs data-[size=default]:sm:max-w-sm",
          overlay.pop,
          overlay.dialog,
          className
        )}
        {...props}
        onEscapeKeyDown={escape.onEscapeKeyDown}
      />
    </AlertDialogPortal>
  );
});
AlertDialogContent.displayName = "AlertDialogContent";

const AlertDialogHeader = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="alert-dialog-header"
      className={cn(
        "grid grid-rows-[auto_1fr] place-items-center gap-1.5 text-center has-data-[slot=alert-dialog-media]:grid-rows-[auto_auto_1fr] has-data-[slot=alert-dialog-media]:gap-x-4 sm:group-data-[size=default]/alert-dialog-content:place-items-start sm:group-data-[size=default]/alert-dialog-content:text-left sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-rows-[auto_1fr]",
        className
      )}
      {...props}
    />
  );
});
AlertDialogHeader.displayName = "AlertDialogHeader";

const AlertDialogFooter = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="alert-dialog-footer"
      className={cn(
        "-mx-4 -mb-4 flex flex-col-reverse gap-2 rounded-b-xl border-t border-[color:var(--v4-line)] bg-muted/50 p-4 group-data-[size=sm]/alert-dialog-content:grid group-data-[size=sm]/alert-dialog-content:grid-cols-2 sm:flex-row sm:justify-end",
        className
      )}
      {...props}
    />
  );
});
AlertDialogFooter.displayName = "AlertDialogFooter";

const AlertDialogMedia = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="alert-dialog-media"
      className={cn(
        "mb-2 inline-flex size-10 items-center justify-center rounded-md bg-muted sm:group-data-[size=default]/alert-dialog-content:row-span-2 *:[svg:not([class*='size-'])]:size-6",
        className
      )}
      {...props}
    />
  );
});
AlertDialogMedia.displayName = "AlertDialogMedia";

const AlertDialogTitle = React.forwardRef<
  React.ComponentRef<typeof AlertDialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Title>
>(({ className, ...props }, ref) => {
  return (
    <AlertDialogPrimitive.Title
      ref={ref}
      data-slot="alert-dialog-title"
      className={cn(
        "sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2",
        className
      )}
      {...props}
    />
  );
});
AlertDialogTitle.displayName = "AlertDialogTitle";

const AlertDialogDescription = React.forwardRef<
  React.ComponentRef<typeof AlertDialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Description>
>(({ className, ...props }, ref) => {
  return (
    <AlertDialogPrimitive.Description
      ref={ref}
      data-slot="alert-dialog-description"
      className={cn(
        "text-muted-foreground text-balance md:text-pretty *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        className
      )}
      {...props}
    />
  );
});
AlertDialogDescription.displayName = "AlertDialogDescription";

const AlertDialogAction = React.forwardRef<
  React.ComponentRef<typeof AlertDialogPrimitive.Action>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Action> &
    Pick<React.ComponentPropsWithoutRef<typeof Button>, "variant" | "size">
>(({ className, variant = "default", size = "default", ...props }, ref) => {
  return (
    <Button variant={variant} size={size} asChild>
      <AlertDialogPrimitive.Action
        ref={ref}
        data-slot="alert-dialog-action"
        className={cn(className)}
        {...props}
      />
    </Button>
  );
});
AlertDialogAction.displayName = "AlertDialogAction";

const AlertDialogCancel = React.forwardRef<
  React.ComponentRef<typeof AlertDialogPrimitive.Cancel>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Cancel> &
    Pick<React.ComponentPropsWithoutRef<typeof Button>, "variant" | "size">
>(({ className, variant = "outline", size = "default", ...props }, ref) => {
  return (
    <Button variant={variant} size={size} asChild>
      <AlertDialogPrimitive.Cancel
        ref={ref}
        data-slot="alert-dialog-cancel"
        className={cn(className)}
        {...props}
      />
    </Button>
  );
});
AlertDialogCancel.displayName = "AlertDialogCancel";

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger
};

.scrim {
  position: fixed;
  inset: 0;
  background-color: var(--v4-scrim);
}
.scrim[data-state="open"] {
  animation: fadeIn var(--v4-duration-slow) var(--v4-ease-fade) both;
}
.scrim[data-state="closed"] {
  animation: fadeOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.pop {
  box-sizing: border-box;
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
}
.dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  display: grid;
  width: calc(100% - 2 * var(--v4-space-16));
  max-width: var(--v4-size-dialog);
  max-height: calc(100dvh - 2 * var(--v4-space-16));
  overflow-y: auto;
  translate: -50% -50%;
}
.dialog[data-state="open"] {
  animation: dialogIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.dialog[data-state="closed"] {
  animation: dialogOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.palette {
  top: 33%;
  max-width: var(--v4-size-dialog-wide);
  overflow: hidden;
  translate: -50% 0;
}
.close[data-slot] {
  position: absolute;
  top: calc(
    var(--v4-space-overlay-inset) + (var(--v4-type-title-line-height) - var(--v4-size-nested-md)) /
      2
  );
  inset-inline-end: calc(
    var(--v4-space-overlay-inset) - (var(--v4-size-nested-md) - var(--v4-size-icon)) / 2
  );
}
.sheet {
  --v4-sheet-from: 100% 0;
}
.sheet[data-side="left"] {
  --v4-sheet-from: -100% 0;
}
.sheet[data-side="top"] {
  --v4-sheet-from: 0 -100%;
}
.sheet[data-side="bottom"] {
  --v4-sheet-from: 0 100%;
}
.sheet[data-state="open"] {
  animation: sheetIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.sheet[data-state="closed"] {
  animation: sheetOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.drawer.drawer[data-vaul-drawer] {
  transition-duration: var(--v4-duration-slow);
  transition-timing-function: var(--v4-ease-spring-soft);
  animation-duration: var(--v4-duration-slow);
  animation-timing-function: var(--v4-ease-spring-soft);
  animation-fill-mode: both;
}
.drawer.drawer[data-vaul-drawer][data-state="closed"] {
  transition-duration: var(--v4-duration-exit-slow);
  transition-timing-function: var(--v4-ease-exit);
  animation-duration: var(--v4-duration-exit-slow);
  animation-timing-function: var(--v4-ease-exit);
}
.handle {
  display: none;
  flex: none;
  width: var(--v4-space-48);
  height: var(--v4-space-4);
  margin: var(--v4-space-12) auto 0;
  border-radius: calc(var(--v4-radius-pop) * var(--corners));
  background-color: var(--v4-control);
}
[data-vaul-drawer-direction="bottom"] > .handle {
  display: block;
}
.scrim.scrim[data-vaul-overlay] {
  animation-duration: var(--v4-duration-slow);
  animation-timing-function: var(--v4-ease-fade);
  animation-fill-mode: both;
}
.scrim.scrim[data-vaul-overlay][data-state="closed"] {
  animation-duration: var(--v4-duration-exit-slow);
  animation-timing-function: var(--v4-ease-exit);
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@keyframes dialogIn {
  from {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes dialogOut {
  to {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes sheetIn {
  from {
    translate: var(--v4-sheet-from);
  }
}
@keyframes sheetOut {
  to {
    translate: var(--v4-sheet-from);
  }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[data-state="open"],
  .sheet[data-state="open"] {
    animation-name: fadeIn;
  }
  .dialog[data-state="closed"],
  .sheet[data-state="closed"] {
    animation-name: fadeOut;
  }
  .drawer.drawer[data-vaul-drawer] {
    transition: none;
  }
  .drawer.drawer.drawer[data-vaul-drawer][data-state="open"] {
    animation-name: fadeIn;
  }
  .drawer.drawer.drawer[data-vaul-drawer][data-state="closed"] {
    animation-name: fadeOut;
  }
}
